const preview=document.getElementById('preview-dialog');
let previewIndex=0,previewCourse='meta',previewToken=0,previewOpener=null,previewOverflow='';
const previewImages=new Map();
function loadSample(sample,priority='high'){
 let promise=previewImages.get(sample.image);if(promise)return promise;
 const full=new Image();full.decoding='async';full.fetchPriority=priority;full.src=sample.image;
 promise=full.decode().then(()=>full).catch(error=>{previewImages.delete(sample.image);throw error});previewImages.set(sample.image,promise);return promise;
}
function showPreview(index){
 const sample=PREVIEWS[previewCourse]?.[index];if(!sample)return;previewIndex=index;const token=++previewToken;
 document.getElementById('preview-page').textContent=`Actual ${previewCourse==='meta'?'Meta':'Practical AI'} PDF · Page ${sample.page} of ${PRODUCTS[previewCourse].pages}`;
 document.getElementById('preview-title').textContent=sample.title;
 const img=document.getElementById('preview-image'),stage=preview.querySelector('.preview-stage'),position=document.getElementById('preview-position');
 // A cached thumbnail appears immediately; the high-resolution sample replaces
 // it as soon as it is decoded. Never leave a blank panel behind sample numbers.
 img.style.visibility='';stage.setAttribute('aria-busy','true');img.src=sample.thumb;img.alt=`Actual course page ${sample.page}: ${sample.title}`;
 document.getElementById('preview-full-link').href=sample.image;
 document.getElementById('preview-caption').textContent=sample.note;
 position.textContent=`Sample ${index+1} of ${PREVIEWS[previewCourse].length} · Loading readable page…`;
 loadSample(sample).then(()=>{if(previewToken===token&&preview.open){img.src=sample.image;stage.setAttribute('aria-busy','false');position.textContent=`Sample ${index+1} of ${PREVIEWS[previewCourse].length}`}}).catch(()=>{if(previewToken===token&&preview.open){stage.setAttribute('aria-busy','false');position.textContent='Small preview shown. Open the readable sample or try again.'}});
 preview.querySelector('[data-preview-prev]').disabled=index===0;
 preview.querySelector('[data-preview-next]').disabled=index===PREVIEWS[previewCourse].length-1;
 stage.scrollTop=0;
}
for(const event of ['pointerover','focusin'])document.addEventListener(event,e=>{
 const link=e.target.closest('[data-preview]');if(!link||navigator.connection?.saveData)return;
 const [id,index]=link.dataset.preview.split(':');const sample=PREVIEWS[id]?.[Number(index)];if(sample)loadSample(sample,'low').catch(()=>{});
});
// Warm only the current course's first sample after initial content is ready.
if((page==='meta'||page==='ai')&&!navigator.connection?.saveData&&!['slow-2g','2g'].includes(navigator.connection?.effectiveType)){
 const warm=()=>{if(document.visibilityState==='visible')loadSample(PREVIEWS[page][0],'low').catch(()=>{})};
 window.addEventListener('load',()=>{if('requestIdleCallback' in window)requestIdleCallback(warm,{timeout:2500});else setTimeout(warm,600)},{once:true});
}
document.addEventListener('click',e=>{
 const link=e.target.closest('[data-preview]');
 if(link){if(typeof preview.showModal!=='function')return;const [id,index]=link.dataset.preview.split(':');if(!Object.hasOwn(PREVIEWS,id)||!PREVIEWS[id][Number(index)])return;e.preventDefault();closeCart();previewOpener=link;previewOverflow=document.body.style.overflow;previewCourse=id;preview.showModal();showPreview(Number(index));document.body.style.overflow='hidden';preview.querySelector('[data-close-preview]').focus();}
 if(e.target.closest('[data-close-preview]'))closePreview();
 if(e.target.closest('[data-preview-prev]'))showPreview(previewIndex-1);
 if(e.target.closest('[data-preview-next]'))showPreview(previewIndex+1);
 if(e.target===preview){const r=preview.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePreview();}
});
function restorePreview(){++previewToken;document.body.style.overflow=previewOverflow;const opener=previewOpener;previewOpener=null;opener?.focus({preventScroll:true})}
function closePreview(){if(!preview.open)return;preview.close();restorePreview()}
preview.addEventListener('cancel',event=>{event.preventDefault();closePreview()});
preview.addEventListener('close',()=>{if(!preview.open&&previewOpener)restorePreview()});
preview.addEventListener('keydown',e=>{
 if(e.key==='Tab'){
  const controls=[...preview.querySelectorAll('button:not([disabled]),a[href],[tabindex="0"]')],index=controls.indexOf(document.activeElement);
  const next=e.shiftKey?(index<=0?controls.length-1:index-1):(index<0||index===controls.length-1?0:index+1);
  e.preventDefault();controls[next]?.focus({preventScroll:true});
 }
 if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();showPreview(previewIndex+(e.key==='ArrowRight'?1:-1));}
});
// Keep native, readable disclosure content; enhance only interaction timing.
const disclosureAnimations=new WeakMap();
function syncSectionToggle(){
 const control=document.querySelector('[data-expand-sections]');if(!control)return;
 const all=[...document.querySelectorAll('#course-curriculum details')].every(d=>d.dataset.targetOpen==='true'||(!d.dataset.targetOpen&&d.open));
 control.setAttribute('aria-expanded',String(all));control.textContent=all?'Collapse all sections':'Expand all sections';
}
function setDisclosure(details,open,animate=true){
 const content=details.querySelector('.disclosure-content');if(!content)return;
 const start=details.open?content.getBoundingClientRect().height:0;
 const previous=disclosureAnimations.get(details);previous?.cancel();
 details.dataset.targetOpen=String(open);
 if(reducedMotion.matches||!animate||typeof content.animate!=='function'){details.open=open;disclosureAnimations.delete(details);syncSectionToggle();return}
 details.open=true;
 const end=open?content.scrollHeight:0;
 const animation=content.animate([{height:`${start}px`,opacity:start?1:0},{height:`${end}px`,opacity:open?1:0}],{duration:200,easing:'cubic-bezier(.2,.7,.2,1)',fill:'both'});
 disclosureAnimations.set(details,animation);
 animation.finished.then(()=>{if(disclosureAnimations.get(details)!==animation)return;details.open=open;animation.cancel();disclosureAnimations.delete(details)}).catch(()=>{});
 syncSectionToggle();
}
document.querySelectorAll('.animated-disclosure>summary').forEach(summary=>summary.addEventListener('click',event=>{event.preventDefault();const details=summary.parentElement;setDisclosure(details,details.dataset.targetOpen?details.dataset.targetOpen!=='true':!details.open)}));
const sectionToggle=document.querySelector('[data-expand-sections]');
if(sectionToggle){sectionToggle.hidden=false;sectionToggle.addEventListener('click',()=>{const open=sectionToggle.getAttribute('aria-expanded')!=='true';document.querySelectorAll('#course-curriculum details').forEach(details=>setDisclosure(details,open,false))});syncSectionToggle()}
const outcomeToggle=document.querySelector('[data-toggle-outcomes]');
if(outcomeToggle){outcomeToggle.hidden=false;const box=outcomeToggle.closest('.outcomes-box');box.classList.add('is-collapsed');outcomeToggle.addEventListener('click',()=>{const open=outcomeToggle.getAttribute('aria-expanded')!=='true';outcomeToggle.setAttribute('aria-expanded',String(open));box.classList.toggle('is-collapsed',!open);outcomeToggle.innerHTML=open?'Show fewer learning outcomes':'Show all learning outcomes'})}
window.addEventListener('pageshow',event=>{
 if(!event.persisted)return;
 try{const saved=JSON.parse(localStorage.getItem('ascore-courses-cart-v1')||'[]');cart=[...new Set(Array.isArray(saved)?saved:[])].filter(id=>typeof id==='string'&&Object.hasOwn(PRODUCTS,id))}catch{cart=[]}
 if(preview.open)closePreview();closeCart();hideToast();renderCart();
});

// Genuine feedback only: the public API includes published, verified purchases.
if(page==='meta'||page==='ai'){
 const button=document.getElementById('leave-course-review'),form=document.getElementById('course-review-form'),status=document.getElementById('course-review-status');let access=null,eligible=false,reviewBusy=false;
 try{const saved=JSON.parse(localStorage.getItem('ascore-review-access-v1')||'{}');if(saved[page]&&/^[a-f0-9]{64}$/.test(saved[page].token)&&typeof saved[page].orderId==='string')access=saved[page]}catch{}
 const authHeaders=()=>({'x-course-order':access.orderId,'x-course-review':access.token});
 courseRequest('/reviews/'+page).then(async data=>{
  if(!data.ready)return;
  const count=Number.isInteger(data.count)&&data.count>=0?data.count:0,rating=typeof data.rating==='number'&&data.rating>=1&&data.rating<=5?data.rating:null;
  if(count&&rating){
   const text=`${rating.toFixed(1)} out of 5 · ${count} ${count===1?'review':'reviews'}`;document.getElementById('course-review-summary').textContent=text;
   const star='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/></svg>';
   document.querySelectorAll('.review-summary,.review-score').forEach(link=>{link.textContent='';const stars=document.createElement('span');stars.className='review-stars';stars.setAttribute('aria-hidden','true');for(let i=0;i<5;i++){const icon=document.createElement('span');icon.className=i<Math.round(rating)?'filled':'empty';icon.innerHTML=star;stars.append(icon)}const label=document.createElement('span');label.textContent=text;link.append(stars,label)});
   const ld=document.querySelector('script[type="application/ld+json"]');try{const product=JSON.parse(ld.textContent);if(product['@type']==='Product'){product.aggregateRating={'@type':'AggregateRating',ratingValue:rating,reviewCount:count,bestRating:5,worstRating:1};ld.textContent=JSON.stringify(product)}}catch{}
  }
  for(const review of Array.isArray(data.reviews)?data.reviews:[]){if(review.courseId!==page||typeof review.author!=='string'||typeof review.body!=='string'||!Number.isInteger(review.rating)||review.rating<1||review.rating>5)continue;const article=document.createElement('article');article.className='published-review';const heading=document.createElement('h3');heading.textContent=review.author;const score=document.createElement('p');score.className='review-rating';score.textContent=`${review.rating} out of 5 · Verified course buyer`;const body=document.createElement('p');body.textContent=review.body;article.append(heading,score,body);document.getElementById('published-course-reviews').append(article)}
  button.disabled=false;status.textContent='Reviews are open to confirmed course buyers and are moderated before publication.';
  if(access){try{const result=await courseRequest('/reviews/eligibility/'+page,{headers:authHeaders()});eligible=result.eligible===true&&!result.alreadySubmitted;if(result.alreadySubmitted){button.disabled=true;status.textContent='Your course review has already been submitted.'}}catch{status.textContent='A confirmed course purchase is required to leave a review.'}}
 }).catch(()=>{status.textContent='Reviews are temporarily unavailable. Please try again later.'});
 button.addEventListener('click',()=>{if(!eligible){status.textContent='A confirmed course purchase is required. Use the browser where you completed your verified course checkout.';return}form.hidden=false;button.hidden=true;document.getElementById('review-author').focus()});
 document.getElementById('cancel-course-review').addEventListener('click',()=>{form.hidden=true;button.hidden=false;button.focus()});
 form.addEventListener('submit',async e=>{e.preventDefault();if(reviewBusy||!eligible)return;const author=document.getElementById('review-author'),rating=document.getElementById('review-rating'),body=document.getElementById('review-body'),consent=document.getElementById('review-publication-consent');
  if(!author.value.trim()||author.value.trim().length>80||Number(rating.value)<1||Number(rating.value)>5||body.value.trim().length<20||body.value.trim().length>2000||!consent.checked){status.textContent='Enter your name, choose a rating, write 20–2,000 characters and confirm publication consent.';form.reportValidity();return}
  reviewBusy=true;const submit=form.querySelector('[type="submit"]');submit.disabled=true;status.textContent='Submitting your review…';
  try{await courseRequest('/reviews',{body:{courseId:page,orderId:access.orderId,author:author.value.trim(),rating:Number(rating.value),body:body.value.trim(),consent:true},headers:authHeaders()});eligible=false;form.hidden=true;button.hidden=false;button.disabled=true;status.textContent='Thank you. Your review is saved for moderation and has not been published yet.';button.focus({preventScroll:true})}catch(error){status.textContent=error.message}finally{reviewBusy=false;submit.disabled=false}
 });
}
